INSERT INTO `artisanat` VALUES (1,'Dakhla','Tapis sahraoui','Tapis traditionnel tissé á la main par les femmes sahraouies, caractérisé par des motifs géométriques et des couleurs vives représentant le désert et l\'océan.','tapis_sahraoui.png'),(2,'Dakhla','Bijoux en argent','Bijoux artisanaux en argent massif, ornés de motifs traditionnels sahraouis, portés lors des cérémonies et f├¬tes locales.','bijoux_argent_dakhla.jpg'),(3,'Dakhla','Objets en cuir de chameau','Maroquinerie artisanale réalisée ├á partir de cuir de chameau, tanné selon des méthodes traditionnelles : sacs, portefeuilles, ceintures.','cuir_chameau.jpeg'),(4,'Dakhla','Poterie sahraouie','Poteries utilitaires et décoratives fabriquées á la main, utilisées traditionnellement pour conserver l\'eau et les aliments dans le désert.','poterie_sahraouie.jpg'),(5,'Dakhla','Vannerie en feuilles de palmier','Objets tressés en feuilles de palmier-dattier : paniers, nattes, corbeilles, reflétant le savoir-faire oasien.','vannerie_dakhla.jpg'),(6,'Laóyoune','Tapis de Laóyoune','Tapis traditionnel saharien aux couleurs chaudes (rouge, orange, brun) représentant les dunes et le coucher de soleil sur le désert.','tapis_laayoune.jpg'),(7,'Laóyoune','Articles en peau de ch ¿vre','Objets utilitaires et décoratifs en peau de ch ¿vre tannée : sacs  á eau traditionnels (guerbas), pochettes, tapis.','peau_chevre.jpg'),(8,'La óyoune','Broderie traditionnelle','Broderie réalisée  á la main sur les vetements traditionnels, notamment sur les melhfas et les daróas, avec des fils de soie colorés.','broderie_laayoune.jpg'),(9,'La├óyoune','Sculpture sur bois','Objets sculptés dans le bois de palmier ou d\'arganier : coffres, petits meubles, ustensiles de cuisine traditionnels.','sculpture_bois_laayoune.jpeg'),(10,'Asilah','Peinture sur soie','┼Æuvres d\'art réalisées sur soie par les artistes locaux, inspirées des fresques murales et de la lumi├¿re particuli├¿re d\'Asilah.','peinture_soie.png'),(11,'Asilah','Céramique artistique','Poterie peinte ├á la main représentant les motifs et les couleurs emblématiques de la médina d\'Asilah : bleu et blanc.','ceramique_asilah.jpg'),(12,'Asilah','Tissage traditionnel','Tissus artisanaux réalisés sur métier ├á tisser traditionnel, utilisés pour la confection de nappes, foulards et v├¬tements.','tissage_asilah.jpg'),(13,'Asilah','Maroquinerie fine','Articles en cuir travaillés avec finesse : sacs, ceintures, porte-documents, ornés de motifs inspirés de l\'architecture locale.','maroquinerie_asilah.png'),(14,'Asilah','Gravure sur cuivre','Objets en cuivre gravés ├á la main : plateaux, théi├¿res, lampes, perpétuant l\'artisanat d\'art andalou.','gravure_cuivre.jpg'),(15,'Zagora','Tapis de la vallée du Dr├óa','Tapis berb├¿re tissé ├á la main par les femmes de la région, avec des motifs géométriques typiques du sud marocain.','tapis_draa_zagora.jpg'),(16,'Zagora','Poteries en terre cuite','Objets utilitaires et décoratifs fabriqués dans les ateliers artisanaux des oasis, cuits au soleil.','poterie_zagora.webp'),(17,'Sa├»dia','Poterie méditerranéenne','Céramique aux couleurs bleues et blanches inspirées de la Méditerranée, fabriquée selon des techniques traditionnelles du nord du Maroc.','poterie_saidia.jpg'),(18,'Sa├»dia','Vannerie en jonc','Paniers, nattes et corbeilles tressés en jonc marin, une tradition artisanale transmise de génération en génération dans la région.','vannerie_saidia.webp'),(19,'Sa├»dia','Broderie de l\'Oriental','Broderie fine réalisée sur le linge de maison et les v├¬tements traditionnels, caractéristique de la région de l\'Oriental marocain.','broderie_oriental.jpg'),(20,'Sa├»dia','Poterie bleue de Sa├»dia','Céramique décorative aux tons bleus évoquant la mer Méditerranée, utilisée pour la décoration intérieure et la vaisselle.','poterie_bleue.jpg'),(21,'Tanger','Bijoux traditionnels du Nord','Bijoux artisanaux en or et perles portés avec la Chedda Tanjaouia lors des mariages.','bijoux_nord.jpeg'),(22,'Tanger','Sebniya','Foulard traditionnel porté avec la Chedda Tanjaouia, décoré et utilisé pour former la coiffe de la mariée.','sebniya.jpg'),(23,'Tétouan','Broderie tétouanaise','Broderie fine d\'inspiration andalouse utilisée pour v├¬tements et décorations.','broderie_tetouan.jpeg'),(24,'Tétouan','Maroquinerie artisanale','Fabrication traditionnelle de sacs, ceintures et accessoires en cuir.','maroquinerie_tetouan.jpg'),(25,'Chefchaouen','Tapis rifains','Tapis en laine tissés ├á la main avec motifs amazighs typiques du Rif.','tapis_chefchaouen.jpg'),(26,'Chefchaouen','Tissage Jbala','Tissus traditionnels rouges et blancs portés par les femmes rurales.','tissage_chefchaouen.webp'),(27,'Marrakech','Ferronnerie artisanale','Lampes et objets décoratifs en métal ciselé fabriqués dans la médina.','ferronnerie_marrakech.jpg'),(28,'Mekn├¿s','Bois sculpté','Meubles et portes décorés avec motifs traditionnels marocains sculptés ├á la main.','bois_meknes.webp'),(29,'Mekn├¿s','Poterie meknessie','Céramique traditionnelle produite dans la région avec décorations artisanales.','poterie_meknes.jpg'),(30,'Agadir','Bijouterie en Argent (Souss)','Artisanat berb├¿re ancestral spécialisé dans le travail de l\'argent et de l\'émail.','agadir_argent.jpg'),(31,'Agadir','Production de l\'Argane','Extraction artisanale de l\'huile d\'argan par les coopératives de femmes du Souss.','agadir_argan.png'),(32,'Agadir','Maroquinerie de Taroudant','Travail du cuir tanné localement pour fabriquer des sacs et des babouches.','agadir_cuir.jfif'),(33,'Essaouira','Marqueterie en bois de Thuya','Art unique de sculpture et d\'incrustation sur bois de thuya, bois rare de la région.','essaouira_artisanat.png'),(34,'Essaouira','Joaillerie en Filigrane','Bijoux en argent finement travaillés en fils de métal, spécialité historique de la ville.','essaouira_argent.jfif'),(35,'Essaouira','Tissage de Couvertures','Tissage de couvertures en laine rayées, typiques de la région de Mogador.','essaouira_tissage.jfif'),(36,'Ifrane','Sculpture sur bois de C├¿dre','Artisanat local utilisant le bois de c├¿dre des for├¬ts environnantes.','ifrane_artisanat.png'),(37,'Ifrane','Tissage de Tapis Moyen Atlas','Tapis berb├¿res épais en laine, con├ºus pour protéger du froid de la montagne.','ifrane_tapis.png'),(38,'Ifrane','Confection de Djellaba','Djellabas lourdes faites ├á la main pour supporter le climat hivernal.','ifrane_djellaba.jpg'),(39,'F├¿s','Poterie Bleue et Zellige','Art millénaire de la céramique émaillée et découpe manuelle du zellige fassi.','fes_artisanat.png'),(40,'F├¿s','Tannage du Cuir (Chouara)','Dabraghe traditionnelle du cuir dans les tanneries millénaires de la médina.','fes_cuir.jpg'),(41,'F├¿s','Dinanderie (Cuivre)','Fabrication d\'objets en cuivre et laiton martelés ├á la main (Place Seffarine).','fes_cuivre.png'),(42,'Casablanca','Ciselure et Bijouterie Moderne','Haut lieu de la création de bijoux modernes et du travail de précision sur métaux précieux.','casa_artisanat.png'),(43,'Casablanca','Couture de Caftan Moderne','Confection de caftans de luxe alliant broderie traditionnelle et coupes modernes.','casa_caftan.png'),(44,'Casablanca','Ferronnerie d\'Art','Travail du fer forgé pour la décoration d\'intérieur et les luminaires.','casa_ferronnerie.png'),(45,'Kénitra','Vannerie de la Plaine (Rotin)','Fabrication d\'objets utilitaires et décoratifs en roseau et en rotin.','kenitra_artisanat.png'),(46,'Kénitra','Poterie du Gharb','Poterie en terre cuite rouge destinée ├á l\'usage domestique et au jardinage.','kenitra_poterie.png'),(47,'Taroudant','Tannage du Cuir et Argent','Dabraghe traditionnelle du cuir et bijoux berb├¿res authentiques.','taroudant_artisanat.png'),(48,'Taroudant','Teinture de la Laine','Coloration artisanale de la laine en utilisant des pigments naturels.','taroudant_teinture.png'),(49,'Oujda','Broderie et Blousa Oujdia','Art de la couture traditionnelle pour la cél├¿bre Blousa du Maroc Oriental.','oujda_artisanat.png'),(50,'Oujda','Menuiserie d\'Art','Fabrication de plafonds peints et bois sculpté pour les riads et maisons.','oujda_bois.png'),(51,'Oujda','Couture du Jabadour','Tenue traditionnelle masculine raffinée, tr├¿s prisée dans l\'Oriental.','oujda_jabadour.png'),(52,'Safi','Céramique Emaillée de Safi','Réputée mondialement pour ses poteries colorées et ses décors floraux.','safi_artisanat.png'),(53,'Safi','Construction de Barques','Charpenterie marine traditionnelle pour la fabrication de bateaux de p├¬che.','safi_marine.png'),(54,'Safi','Forge Traditionnelle','Outils agricoles et objets en fer forgé fabriqués par les forgerons locaux.','safi_forge.png'),(55,'Taza','Tissage Rural des Ghiata','Confection de tapis et de tissus en laine brute par les tribus locales.','taza_artisanat.png'),(56,'Taza','Fabrication de Tajines','Poterie de terre cuite robuste utilisée pour la cuisson au feu de bois.','taza_tajine.png'),(57,'Taza','Maroquinerie Rurale','Sacs et accessoires en cuir brut fabriqués par les montagnards.','taza_cuir.png'),(58,'Nador','Poterie Rifaine Traditionnelle','Poterie en terre cuite aux motifs berb├¿res anciens, spécifique au Rif.','nador_artisanat.png'),(59,'Nador','Vannerie de l\'Oriental','Objets en osier et alfa fabriqués par les artisans des montagnes du Rif.','nador_vannerie.png'),(60,'Nador','Travail du Fer Forgé','Réalisation de grilles et objets décoratifs avec des motifs berb├¿res du Nord.','nador_fer.png'),(61,'Azrou','Tapis de l\'Atlas (Beni M\'Guild)','Tapis en laine épaisse aux motifs géométriques, emblématiques du Moyen Atlas.','azrou_artisanat.png'),(62,'Azrou','Sculpture sur bois de C├¿dre','Objets décoratifs et coffrets sculptés dans le bois de c├¿dre des for├¬ts d\'Azrou.','azrou_bois.png'),(63,'Azrou','Tissage de Hanbel','Tissage de couvertures lég├¿res et colorées en laine et coton.','azrou_hanbel.jpg'),(64,'Taourirt','Tapis de lÔÇÖOriental','Tapis berb├¿re aux motifs géométriques et couleurs chaudes, tissé ├á la main par les femmes de la tribu des Beni Bouzeggou.','tapis_taourirt.jpg'),(65,'Taourirt','Poterie de Taourirt','Céramique utilitaire et décorative en terre cuite rouge, fabriquée selon des méthodes ancestrales.','poterie_taourirt.jpg'),(66,'Berkane','Tissage de la laine (Beni Snassen)','Artisanat de tissage traditionnel propre aux tribus de la région de l\'Oriental.','berkane_artisanat.png'),(67,'Berkane','Vannerie en Palmier Doum','Fabrication de paniers et chapeaux ├á partir des fibres de palmier doum local.','berkane_doum.png'),(68,'Berkane','Poterie Rustique','Poterie utilitaire simple utilisée traditionnellement dans les campagnes de l\'Oriental.','berkane_poterie.jfif'),(69,'Oualidia','Fabrication de Filets','Savoir-faire local dans le tissage et la réparation des filets de p├¬che traditionnelle.','fabrication_filets_oualidia.jpg'),(70,'Oualidia','Poterie de bord de mer','Poteries utilitaires simples destinées ├á la cuisson et au service des produits de la mer.','poterie_mer_oualidia.jpg'),(71,'Haut Atlas','Poignards d\'Azilal','Coutellerie artisanale décorée d\'argent et de laiton.','azilal_poignard.png'),(72,'Haut Atlas','Tissage de Hanbel','Couvertures en laine colorée aux motifs berb├¿res.','atlas_hanbel.webp'),(73,'El Jadida','Broderie Doukkalia','Travail manuel délicat aux motifs géométriques et couleurs vives.','doukkala_broderie.jpg'),(74,'El Jadida','Sellerie de Tbourida','Fabrication de selles richement ornées pour les cavaliers de la région.','eljadida_selles.avif'),(75,'Ouka├»meden','Bonnet et gants en laine','Accessoires en laine naturelle tricotés ├á la main, parfaits pour les sports dÔÇÖhiver.','bonnet_laine_oukaimeden.jpg'),(76,'Ouka├»meden','Poterie de montagne','Petites poteries locales en terre cuite, utilisées pour conserver les herbes de montagne.','poterie_oukaimeden.jpg'),(77,'Al Hoceima','Poterie Rifaine','Poterie traditionnelle fabriquée ├á la main dans les villages du Rif.','poterie_hoceima.png'),(78,'Al Hoceima','Vannerie','Paniers et objets tressés en palmier et paille.','vannerie_hoceima.png'),(79,'Al Hoceima','Broderie Traditionnelle','V├¬tements et textiles brodés ├á la main.','broderie_hoceima.png'),(80,'Imlil','Tapis Berb├¿res','Tapis en laine faits main avec motifs amazighs.','tapis_imlil.png'),(81,'Imlil','Couvertures en Laine','Textiles traditionnels en laine naturelle.','laine_imlil.png'),(82,'Ouarzazate','Tapis Ouzguita','Tapis colorés aux motifs géométriques du Sud marocain.','tapis_ouarzazate.png'),(83,'Ouarzazate','Bijoux Berb├¿res','Bijoux en argent avec pierres naturelles.','bijoux_ouarzazate.png'),(84,'Ouarzazate','Vannerie','Objets artisanaux en fibres naturelles.','vannerie_ouarzazate.png'),(85,'Merzouga','Tapis Sahariens','Tapis berb├¿res et touaregs faits main.','tapis_merzouga.png'),(86,'Merzouga','Bijoux Touaregs','Bijoux traditionnels en argent gravé.','bijoux_merzouga.png'),(87,'Merzouga','Poterie Saharienne','Objets en argile fabriqués localement.','poterie_merzouga.png'),(88,'Rabat','Tapis de Rabat','Tapis traditionnels faits ├á la main avec motifs géométriques et floraux.','tapis_rabat.png'),(89,'Rabat','Poterie Oulja','Céramique artisanale avec influence amazighe et andalouse.','poterie_rabat.png'),(90,'Rabat','Maroquinerie','Objets en cuir : sacs, poufs, ceintures.','cuir_rabat.png'),(91,'Moyen Atlas','Tapis Zayane Authentique','Tapis berb├¿re cél├¿bre pour sa couleur rouge vif et ses motifs noirs géométriques.','moyen_atlas_tapis.jpg'),(92,'Moyen Atlas','Djellaba de l\'Atlas','Confection artisanale en laine fine, typique des régions froides de la montagne.','moyen_atlas_djellaba.jfif'),(93,'Kelaat M\'Gouna','Eau de rose','Produit emblématique extrait des roses locales, utilisé en cosmétique et cuisine.','eau_rose.jpg'),(94,'Kelaat M\'Gouna','Cosmétiques naturels','Produits ├á base de rose : huiles, cr├¿mes et parfums.','cosmetique_rose.jpg'),(95,'Kelaat M\'Gouna','Tapis berb├¿res','Tapis faits ├á la main avec motifs traditionnels.','tapis_berbere.jpg'),(96,'Kelaat M\'Gouna','Objets en poterie','Poterie artisanale locale utilisée au quotidien.','poterie.jpg');
