--
-- Table structure for table `attractions`
--

DROP TABLE IF EXISTS `attractions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `attractions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nom_ville` varchar(120) DEFAULT NULL,
  `nom` varchar(120) DEFAULT NULL,
  `description` text,
  `image_path` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `nom_ville` (`nom_ville`),
  CONSTRAINT `attractions_ibfk_1` FOREIGN KEY (`nom_ville`) REFERENCES `villes` (`nom_ville`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=170 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `attractions`
--

LOCK TABLES `attractions` WRITE;
/*!40000 ALTER TABLE `attractions` DISABLE KEYS */;
INSERT INTO `attractions` VALUES (1,'Dakhla','Lagune de Dakhla','Une lagune magnifique o├╣ la mer et le désert se rencontrent, idéale pour observer les oiseaux et les paysages marins. et offre des conditions parfaites pour le kitesurf et la planche ├á voile gr├óce aux vents constants.','LaguneDakhla.jpg'),(2,'Dakhla','Plage de Foum El Oued','Une étendue de sable doré sauvage, bordée par lÔÇÖocéan Atlantique et ouverte aux vents. Elle est particuli├¿rement adaptée au kitesurf et au surf, avec de grandes vagues et des vents réguliers, tout en offrant un cadre naturel préservé o├╣ le désert et lÔÇÖocéan se rencontrent.','PlageFoumElOued.jpg'),(3,'Dakhla','Parc National de Khnifiss','Réserve naturelle protégée au sud de Dakhla, cél├¿bre pour sa biodiversité et ses zones humides. Le parc abrite de nombreuses esp├¿ces dÔÇÖoiseaux migrateurs et marins, et offre un paysage unique m├¬lant désert et lagune.','ParcNationalKhnifiss.jpg'),(4,'Dakhla','├Äle du Dragon','Une petite ├«le située au c┼ôur de la lagune, accessible ├á marée basse. Elle offre une vue panoramique exceptionnelle sur la lagune et le désert environnant.','├ÄleduDragon.jpg'),(5,'Dakhla','Source Thermale Asmaa','Une source dÔÇÖeau chaude naturelle située pr├¿s de la lagune. Elle est connue pour son cadre paisible et ses propriétés relaxantes.','SourceThermaleAsmaa.webp'),(6,'Dakhla','Centre-ville de Dakhla','Le c┼ôur urbain de la ville regroupant les principales administrations, commerces et espaces publics. Il refl├¿te le développement moderne et lÔÇÖorganisation de la ville.','CentrevilleDakhla.png'),(7,'Dakhla','Place Hassan II','Une place centrale emblématique utilisée pour les rassemblements et événements locaux. Elle représente un point de rencontre important dans la ville.','PlaceHassanII.png'),(8,'Dakhla','Marché Central','Un espace commercial animé o├╣ se vendent produits locaux et artisanat. Il refl├¿te la vie quotidienne et lÔÇÖidentité locale.','MarchéCentral.jpeg'),(9,'Dakhla','Grande Mosquée de Dakhla','Un édifice religieux important au sein de la ville. Elle se distingue par son architecture sobre et son r├┤le spirituel.','GrandeMosquéeDakhl.jpg'),(10,'La├óyoune','Oued Sakia El Hamra','Un oued emblématique traversant la ville. Il représente un élément naturel important lié ├á lÔÇÖhistoire et au paysage urbain.','OuedSakiaElHamra.png'),(11,'La├óyoune','Place Mechouar','Une grande place centrale utilisée pour les événements et rassemblements. Elle constitue un rep├¿re urbain majeur.','PlaceMechouar.jpg'),(12,'La├óyoune','Grande Mosquée de La├óyoune','Un édifice religieux important de la ville. Elle se distingue par son architecture moderne et son r├┤le spirituel.','GrandeMosqueeLaayoune.jpg'),(13,'La├óyoune','Port de La├óyoune','Un port stratégique lié aux activités de p├¬che et au commerce maritime. Il joue un r├┤le économique clé pour la région.','PortLaayoune.jpeg'),(14,'La├óyoune','Centre-ville de La├óyoune','Un espace urbain regroupant administrations, commerces et services. Il refl├¿te le développement moderne de la ville.','CentrevilleLaayoune.jpg'),(15,'Asilah','Médina dÔÇÖAsilah','Une médina fortifiée aux ruelles blanches et paisibles. Elle est connue pour son harmonie architecturale et son ambiance artistique.','MedinaAsilah.jpg'),(16,'Asilah','Tour de Borj Al Kamra','Une tour historique située pr├¿s des remparts,elle constitue un rep├¿re architectural important La tour Al Kamra (ou Borj Al Kamra) dÔÇÖAsilah, construite entre 1505 et 1509 sous lÔÇÖoccupation portugaise par le roi Emmanuel Ier, servait de résidence ├á sa fille et remplissait des fonctions militaires et civiles. B├ótie en pierre et chaux avec deux étages, elle comprenait une prison, des locaux militaires et la résidence du gouverneur. Dégradée au fil du temps, elle a été restaurée dans les années 1990 gr├óce ├á la fondation Clouste Gulbenkian et inaugurée en 1994 par le roi Mohammed VI.','BorjAlKamra.jpeg'),(17,'Asilah','Murales Artistiques','Des fresques murales renouvelées réguli├¿rement. Elles refl├¿tent le caract├¿re artistique et culturel de la ville.','MuralesAsilah.jpg'),(18,'Asilah','Port dÔÇÖAsilah','Un petit port traditionnel intégré au paysage urbain. Il illustre le lien entre la ville et lÔÇÖocéan. Le port dÔÇÖAsilah est un petit port de p├¬che traditionnel, animé par les p├¬cheurs locaux. Il refl├¿te le mode de vie maritime de la ville et constitue ├á la fois un lieu de travail, un point dÔÇÖéchanges commerciaux et un attrait touristique pour les visiteurs souhaitant découvrir la p├¬che locale et lÔÇÖanimation du port.','PortAsilah.jpg'),(19,'Asilah','Remparts Portugais','Des fortifications historiques longeant lÔÇÖocéan Atlantique. Elles témoignent du passé historique de la ville. Les remparts portugais dÔÇÖAsilah, construits au XVIßÁë si├¿cle, entourent la médina et témoignent de lÔÇÖoccupation portugaise. Ces fortifications, bien conservées, servaient ├á protéger la ville des invasions et constituent aujourdÔÇÖhui un patrimoine historique majeur, offrant des promenades panoramiques le long des murs.','RempartsAsilah.jpg'),(20,'Zagora','Palmeraie de Zagora','Une vaste palmeraie longeant la vallée du Dr├óa. Elle constitue un élément naturel central du paysage.','PalmeraieZagora.jpg'),(21,'Zagora','Panneau Tombouctou 52 Jours','Un panneau emblématique rappelant les anciennes routes caravani├¿res. Il symbolise lÔÇÖhistoire saharienne de la région.','Tombouctou52.jpg'),(22,'Zagora','Oasis de Tinfou','Une oasis située aux portes du désert. Elle marque la transition entre zones habitées et paysages sahariens. Un mélange de charme, de modernité et de valeurs s├╗res.','OasisTinfou.jpg'),(23,'Zagora','Kasbahs Traditionnelles','Des constructions en terre reflétant lÔÇÖarchitecture locale. Elles témoignent du patrimoine historique de la région. Une kasbah est une forteresse traditionnelle du Maghreb, généralement carrée avec quatre tours, o├╣ vivait le seigneur local, sa famille et ses ouvriers. Au Sud du Maroc, elle servait aussi ├á accueillir les caravanes vers le Sahara. Construite en pierres et en pisé, elle est lÔÇÖéquivalent des ch├óteaux forts européens.','KasbahsZagora.jpg'),(24,'Zagora','Dunes du Dr├óa','Des étendues de sable caractéristiques du sud marocain. Elles offrent un paysage désertique authentique.','DunesDraa.jpg'),(25,'Sa├»dia','Plage de Sa├»dia','Une longue plage de sable fin bordée par la mer Méditerranée. Elle se distingue par son étendue et son cadre naturel ouvert.','PlageSaidia.jpg'),(26,'Sa├»dia','Marina de Sa├»dia','Un port de plaisance moderne intégré au paysage c├┤tier. Il symbolise le développement urbain et maritime de la ville.','MarinaSaidia.jpg'),(27,'Sa├»dia','Station Balnéaire de Sa├»dia','Un vaste espace aménagé comprenant des infrastructures modernes. Il représente un p├┤le important de développement local.','StationBalneaireSaidia.png'),(28,'Sa├»dia','Embouchure de la Moulouya','Une zone naturelle o├╣ le fleuve Moulouya rejoint la mer. Elle offre un paysage écologique remarquable.','EmbouchureMoulouya.jpeg'),(29,'Sa├»dia','Centre-ville de Sa├»dia','Un espace urbain regroupant commerces et services de proximité. Il refl├¿te la vie quotidienne de la ville. Le centre-ville de Sa├»dia est le c┼ôur animé de la ville, o├╣ se concentrent les commerces, restaurants, cafés et h├┤tels. CÔÇÖest aussi l├á que lÔÇÖon trouve la promenade principale le long de la plage, les marchés locaux, et les infrastructures touristiques qui font de Sa├»dia une destination prisée pour ses plages et activités balnéaires.','CentrevilleSaidia.png'),(30,'Tanger','Médina de Tanger','Centre historique avec ruelles, marchés, cafés et artisanat traditionnel.','Medina_Tanger.jpg'),(31,'Tanger','Kasbah de Tanger','Ancienne forteresse avec vues panoramiques et musée des cultures méditerranéennes.','Kasbah_Tanger.jpeg'),(32,'Tanger','Cap Spartel','Promontoire o├╣ se rencontrent lÔÇÖocéan Atlantique et la Méditerranée, avec phare emblématique.','Cap_Spartel.png'),(33,'Tanger','Grottes dÔÇÖHercule','For