INSERT INTO `patrimoine_vestimentaire` VALUES (1,'Dakhla','La Dar├óa','Tenue traditionnelle sahraouie portée par les hommes, ample et adaptée au climat désertique.','Dar├óa.png'),(2,'Dakhla','Melhfa sahraouie','Voile traditionnel porté par les femmes sahraouies, symbole dÔÇÖélégance et dÔÇÖidentité culturelle.','MelhfaDraa.png'),(3,'Dakhla','Burnous sahraoui','Cape traditionnelle utilisée pour se protéger du froid, du vent et du sable.','Litham.avif'),(4,'Dakhla','Litham','Voile porté par les hommes sahraouis pour se protéger du soleil et des temp├¬tes de sable.','Litham.jpg'),(5,'Dakhla','Bijoux sahraouis','Bijoux traditionnels en argent portés lors des f├¬tes et cérémonies, reflétant la culture hassanie.','Bijoux_sahraouis.jpg'),(6,'La├óyoune','La Dar├óa','Tenue traditionnelle sahraouie portée par les hommes, symbole du savoir-faire vestimentaire transmis au sein de Dar Derra├óa.','Dar├óa.jpg'),(7,'La├óyoune','Melhfa sahraouie','Voile traditionnel féminin confectionné dans le cadre de la couture traditionnelle, représentant lÔÇÖélégance et lÔÇÖidentité sahraouie.','MelhfaLa├óyoune.jpg'),(8,'La├óyoune','Litham','Voile masculin traditionnel protégeant du soleil et du sable, élément du patrimoine vestimentaire sahraoui.','Litham.avif'),(9,'La├óyoune','Bijoux sahraouis','Bijoux artisanaux en argent issus de lÔÇÖorf├¿vrerie traditionnelle, valorisés par les formations de lÔÇÖInstitut des arts traditionnels.','Bijoux_sahraouis.jpg'),(10,'La├óyoune','Burnous sahraoui','Cape traditionnelle portée dans les régions sahariennes, utilisée lors des périodes froides ou venteuses.','Burnous sahraoui.jpg'),(11,'Asilah','Mendil','Tissu de coton ├á rayures rouges et blanches, noué autour de la taille, emblématique des femmes Jbala.','Mendil.jpg'),(12,'Asilah','Chachia','Large chapeau de paille orné de pompons en laine colorés, typique de la région du Nord.','Chachia.jpg'),(13,'Asilah','Caftan Chamali','Caftan ├á la coupe droite et épurée, souvent réalisé dans des tissus légers et nobles pour les festivités c├┤ti├¿res.','CaftanChamali.jpg'),(14,'Asilah','Bijoux artisanaux','Bijoux fabriqués par les artisans locaux, souvent en argent et pierres naturelles.','BijouxBerberes.png'),(15,'Zagora','Melhfa Dra├óouia','Long tissu drapé noir ou coloré, porté par les femmes du Dr├óa pour se protéger de la chaleur.','MelhfaDraa.png'),(16,'Zagora','Tidriat','Parure de t├¬te traditionnelle ornée de perles et de pi├¿ces d\'argent typique de la vallée du Dr├óa.','Tidriat.jpg'),(17,'Zagora','Caftan du désert','V├¬tement long et coloré porté par les femmes sahariennes.','CaftanDesert.jpg'),(18,'Zagora','Bijoux berb├¿res','Accessoires artisanaux représentant le patrimoine culturel du désert.','BijouxBerberes.png'),(19,'Zagora','Ch├óle berb├¿re brodé','foulard tissé coloré, design Zagora.','Ch├óle berb├¿re brodé.webp'),(20,'Zagora','Burnous','Cape traditionnelle pour se protéger du soleil et du sable.','Burnous_zagora.webp'),(21,'Zagora','Khandra','Pi├¿ce de tissu lourd, souvent sombre, utilisée comme manteau ou protection lors des déplacements dans le désert.','Khandra_zagora.jpg'),(22,'Sa├»dia','Caftan marocain','Tenue traditionnelle portée lors des f├¬tes et mariages.','Caftan.png'),(23,'Sa├»dia','Djellaba','V├¬tement traditionnel pour tous les jours.','Djellaba.png'),(24,'Sa├»dia','Babouches','Chaussures traditionnelles marocaines.','Babouches.jpg'),(25,'Sa├»dia','Tenue de Reggada','Tenue masculine composée d\'une chemise traditionnelle et d\'un gilet, portée pour la danse guerri├¿re du m├¬me nom.','Reggada.png'),(26,'Sa├»dia','Bijoux berb├¿res','Accessoires en argent ou métal ornés de motifs traditionnels, accompagnant les tenues féminines lors des f├¬tes et occasions spéciales.','BijouxBerberes.png'),(27,'Sa├»dia','Chadda de l\'Oriental','Parure de t├¬te sophistiquée portée par les mariées, spécifique aux traditions de l\'Est marocain.','Chadda.jpg'),(28,'Tanger','Djellaba masculine','Tunique longue portée par les hommes de Tanger, avec manches larges et capuche. Fabriquée en laine ou coton, souvent aux couleurs sobres comme le marron, le bleu foncé ou le beige. La djellaba est portée lors des f├¬tes religieuses, mariages et cérémonies culturelles, parfois ornée de broderies simples sur le col et les manches, reflétant l\'identité culturelle tangerine.','Djellaba_masculine.jfif'),(29,'Tanger','Caftan féminin','Robe longue traditionnelle portée par les femmes de Tanger, fabriquée en soie, satin ou velours, avec broderies complexes et motifs dorés. Accompagnée de ceintures et bijoux traditionnels, elle est utilisée lors des mariages, f├¬tes religieuses et événements officiels. Le caftan représente la richesse et le raffinement du patrimoine vestimentaire tangerin.','Caftan_féminin.jpeg'),(30,'Tanger','Haik','Grand voile blanc couvrant le corps de la t├¬te aux pieds, porté par les femmes lors des sorties ou cérémonies religieuses. Il symbolise la pudeur et l\'identité culturelle marocaine traditionnelle, encore utilisé dans certaines familles conservatrices de Tanger.','Haik.webp'),(31,'Tétouan','Caftan Chamali','Contrairement ├á la coupe droite de F├¿s, le caftan de Tétouan est réputé pour sa coupe plus ample et souvent plus courte, appelée Caftan Chamali.','Caftan_Chamali.jpeg'),(32,'Tétouan','Caftan Khanjar','Pi├¿ce spécifique ├á la région, caractérisée par une coupe large, des manches évasées, et une broderie unique en forme d\'ovo├»de sur le plastron, ornée de boutons Lacade.','Caftan_Khanjar.jpg'),(33,'Tétouan','Ha├»k','Voile ancestral blanc ou écru, drapé sur le corps, tr├¿s répandu dans le nord pour la modestie et la protection solaire. Fabriqué en laine fine ou parfois en soie.','Ha├»k.jfif'),(34,'Tétouan','Keswa El Kbira','Tenue de la mariée andalouse-tétouanaise, ornée de broderies dorées, de perles et de velours. Aussi appelée Lebssa el kbira ou Taj.','Keswa_El_Kbira.jpg'),(35,'Chefchaouen','Mendil (Jbala)','Tissu rouge et blanc, porté sur les épaules ou autour de la taille par les femmes dans les zones rurales, symbole de la culture Jbala.','Mendil_Jbala.jpeg'),(36,'Chefchaouen','Chachia Jeblia','Chapeau traditionnel du nord du Maroc, notamment dans la région de Jebala, symbole d\'identité et d\'élégance, souvent en laine feutrée.','Chachia_Jeblia.jpeg'),(37,'Chefchaouen','Ha├»k','Grand voile blanc en laine ou coton drapant le corps, symbole de modestie, encore présent dans le nord du Maroc.','Ha├»k.jpeg'),(38,'Chefchaouen','Djellaba en laine locale','Long v├¬tement ample fabriqué en laine locale, typique de la région, souvent porté par hommes et femmes.','Chefchaouen_Djellaba_en laine_locale.jpeg'),(39,'Chefchaouen','Selham','Cape traditionnelle en laine portée pour se protéger du froid, typique de la culture montagnarde Jbala.','Selham.jpeg'),(40,'Chefchaouen','Tissus tissés artisanaux','Tissus faits main vendus dans les coopératives locales, utilisés pour v├¬tements et accessoires.','Tissus_tissés_artisanaux.jfif'),(41,'Chefchaouen','Babouches traditionnelles','Chaussures en cuir ou tissu tissé, caractéristiques de lÔÇÖartisanat local du Rif.','Babouches_traditionnelles.jfif'),(42,'Chefchaouen','Articles en cuir artisanaux','Sacs, ceintures et accessoires fabriqués par des artisans locaux, reflets du patrimoine chaoueni.','Articles_en_cuir _artisanaux _Chefchaouen.jpeg'),(43,'Chefchaouen','Couvertures et plaids en laine tissée','Couvertures et plaids faits ├á la main en laine, symboles du savoir-faire textile de la région.','Couvertures_plaids_en_laine_tissée.jpeg'),(44,'Marrakech','Djellaba','Tunique longue traditionnelle portée par hommes et femmes, souvent en laine ou coton, colorée ou neutre.','Djellaba.jpeg'),(45,'Marrakech','Kaftan','Robe féminine élégante, brodée et portée lors des mariages et grandes occasions.','Kaftan.png'),(46,'Marrakech','Gandoura','V├¬tement ample et léger, souvent porté en été, simple et confortable.','Gandoura.png'),(47,'Marrakech','Babouches','Chaussures traditionnelles marocaines, en cuir souple, souvent pointues et colorées','Babouches.png'),(48,'Mekn├¿s','Mansouria','Tenue traditionnelle portée par les hommes et les femmes, souvent associée ├á l\'uniforme du makhzen, historiquement liée ├á la cour du sultan Ahmed al-Mansour.','Mansouria.jfif'),(49,'Mekn├¿s','Djellaba','V├¬tement long ├á capuche porté par les hommes et les femmes, symbole de l\'habillement quotidien marocain, souvent en laine ou coton.','Djellaba.png'),(50,'Mekn├¿s','Caftan Meknassi','Version locale du caftan marocain féminin, richement brodée, portée lors des mariages et grandes cérémonies.','Caftan Meknassi.jpeg'),(51,'Mekn├¿s','Takchita','Tenue féminine traditionnelle composée de deux robes superposées, souvent ornée de broderies et bijoux, portée pour les mariages et f├¬tes importantes.','Takchita.png'),(52,'Mekn├¿s','Babouches','Chaussures traditionnelles marocaines en cuir, souvent colorées ou brodées, portées par hommes et femmes.','Babouches.jpeg'),(53,'Agadir','Le Taguennout (Voile brodé)','Un grand voile noir rectangulaire porté par les femmes du Souss, richement orné de broderies colorées en soie ou en laine aux extrémités. Il symbolise l\'élégance et l\'appartenance tribale.','taguennout_agadir.jfif'),(54,'Agadir','Les Bijoux en Argent (Bijouterie de Tiznit/Souss)','Agadir est la vitrine des bijoux berb├¿res en argent massif, souvent décorés d\'émail jaune et vert ou de pierres de cire. Les fibules (Tawnza) sont les pi├¿ces ma├«tresses de cette parure.','bijoux_argent_souss.png'),(55,'Agadir','La Cherbil (Babouche du Souss)','Babouches traditionnelles souvent brodées de fils de soie dorés ou argentés pour les femmes, ou en cuir jaune simple (Ibouklyen) pour les hommes, adaptées au terrain montagneux et aride.','cherbil_souss.webp'),(56,'Essaouira','Le Ha├»k Souiri','Un long drap de laine ou de coton blanc pur qui enveloppe le corps de la femme. Contrairement ├á d\'autres régions, le Ha├»k d\'Essaouira est réputé pour sa finesse et sa blancheur éclatante, symbole de l\'élégance pudique des femmes de Mogador.','haik_souiri_essaouira.jpg'),(57,'Essaouira','Les Bijoux en Filigrane d\'Argent','Un héritage précieux de l\'artisanat judéo-marocain. Ce sont des bijoux en argent massif travaillés avec des fils de métal extr├¬mement fins entrelacés, créant des motifs de dentelle métallique d\'une grande précision.','bijoux_filigrane_argent.jpg'),(58,'Essaouira','La Tenue Rituelle Gnaoua','Composée d\'une tunique satinée colorée (souvent rouge, bleue ou verte), brodée de cauris (petits coquillages) et accompagnée d\'un \"Taqia\" (bonnet) orné de perles. C\'est le costume sacré utilisé lors des Lila (cérémonies mystiques).','tenue_gnaoua_rituelle.webp'),(59,'Essaouira','Les Babouches en cuir de Mogador','Souvent fabriquées ├á base de cuir de ch├¿vre local de haute qualité. Elles se déclinent en mod├¿les simples pour les hommes (souvent jaunes) et richement brodées de fils de soie pour les femmes, adaptées ├á la marche dans les ruelles pavées.','babouches_cuir_mogador.avif'),(60,'Ifrane','La Jellaba en Laine (Bziouia)','Une jellaba épaisse tissée ├á la main, indispensable pour affronter les hivers rigoureux de l\'Atlas. Elle est souvent de couleur naturelle (blanc cassé ou marron).','jellaba_laine_ifrane.jpg'),(61,'Ifrane','Le Tapis de l\'Atlas (Marmoucha)','Tapis berb├¿re aux motifs géométriques simples, connu pour sa laine épaisse et soyeuse qui servait autrefois ├á protéger du froid des montagnes.','tapis_marmoucha_atlas.webp'),(62,'Ifrane','La Handira','Une cape traditionnelle berb├¿re richement décorée de paillettes, portée par les femmes lors des mariages et des cérémonies tribales du Moyen Atlas.','handira_moyen_atlas.jfif'),(63,'Ifrane','La tenue de Ski et Montagne','Un patrimoine moderne de la ville ; Ifrane est l\'un des rares endroits au Maroc o├╣ l\'équipement de sports d\'hiver fait partie du paysage quotidien.','ski_montagne_ifrane.jpg'),(64,'F├¿s','Le Tarbouche Fassi','Le cél├¿bre chapeau rouge en feutre avec un gland noir. Symbole de l\'élite intellectuelle et administrative du Maroc pendant des décennies.','tarbouche_fassi_rouge.webp'),(65,'F├¿s','Le Caftan de F├¿s (Ntaa)','Un caftan de velours précieux, richement brodé au fil d\'or (Skalli). C\'est la pi├¿ce ma├«tresse du trousseau de la mariée fassie.','caftan_ntaa_fes.jfif'),(66,'F├¿s','La Djellaba Fassie','Tissée avec une laine tr├¿s fine et lég├¿re, elle se distingue par son élégance sobre et sa coupe impeccable, portée par les notables de la ville.','djellaba_fassie_notable.jpg'),(67,'F├¿s','La Babouche de F├¿s (Cherbil)','Reconnue pour son bout pointu et sa finesse, elle est souvent brodée ├á la main par les artisans de la médina avec des motifs floraux.','cherbil_fassi_brode.jfif'),(68,'Casablanca','La Djellaba Citadine','Une coupe moderne et élégante, souvent portée par les femmes actives de la métropole.','djellaba_citadine_casa.jpg'),(69,'Kénitra','Le Caftan du Gharb','Une version raffinée du caftan marocain portée lors des cérémonies dans la plaine du Gharb, connue pour ses broderies délicates.','caftan_gharb_kenitra tradition.jpg'),(70,'Kénitra','La Jellaba de Ma├ómora','Une jellaba traditionnelle en laine lég├¿re ou en coton, adaptée au climat tempéré et aux activités foresti├¿res de la région.','jellaba_maamora_kenitra.jpg'),(71,'Taroudant','Le Tamelhaft','Un grand drapé noir ou bleu porté par les femmes roudanaises, symbole de pudeur et d\'élégance traditionnelle.','tamelhaft_roudani_noir.jpg'),(72,'Taroudant','Bijoux en Argent','Taroudant est réputée pour ses parures berb├¿res artisanales en argent massif ciselé.','bijoux_argent_taroudant.jpg'),(73,'Oujda','La Blousa Oujdia','Robe traditionnelle raffinée, ornée de perles, symbole de l\'élégance féminine orientale.','blousa_oujdia_perlee.jfif'),(74,'Oujda','Le Burnous (Selham)','Manteau de laine traditionnel porté par les hommes lors des grandes cérémonies.','selham_burnous_oujda.png'),(75,'Safi','Le Caftan de Safi','Un style de caftan sobre mais élégant, souvent porté lors des f├¬tes de la région.','caftan_safiot_elegant.jpg'),(76,'Safi','La Tenue des Potiers','Le tablier traditionnel et les v├¬tements de travail des artisans céramistes.','tenue_potiers_safi.png'),(77,'Taza','La Jellaba de Taza','Reconnaissable par sa laine épaisse et ses motifs ruraux, adaptée au climat froid des montagnes.','jellaba_taza_laine.jfif'),(78,'Taza','Bijoux de Taza Haut','Artisanat traditionnel en argent ciselé, autrefois spécialité de la médina.','bijoux_argent_taza.jpg'),(79,'Nador','Le Chapeau Taraza','Chapeau traditionnel rifain en paille décoré de pompons colorés.','chapeau_taraza_nador_rif.jfif'),(80,'Nador','Bijoux en Argent','Artisanat berb├¿re typique de la région du Rif aux motifs géométriques.','bijoux_argent_berbere_nador.jpg'),(81,'Azrou','Tapis d\'Azrou (Beni M\'guild)','Tapis en laine épaisse aux couleurs naturelles, réputé mondialement.','tapis_beni_m_guild_azrou.jpg'),(82,'Azrou','Artisanat du Bois de C├¿dre','Objets sculptés ├á la main diffusant une odeur naturelle unique.','artisanat_bois_cedre_azrou.jfif'),(83,'Taourirt','Tissages de l\'Oriental','Couvertures et tapis artisanaux fabriqués localement en laine.','tissages_laine_taourirt.webp'),(84,'Taourirt','Haik de l\'Oriental','V├¬tement traditionnel porté historiquement dans cette zone.','haik_traditionnel_taourirt.jfif'),(85,'Berkane','La Jellaba de Beni Snassen','Tenue traditionnelle en laine fine, symbole du savoir-faire artisanal des tribus locales.','jellaba_beni_snassen_berkane.jfif'),(86,'Oualidia','Tenue des Marins','V├¬tements pratiques et simples utilisés par les p├¬cheurs et ostréiculteurs.','tenue_marins_oualidia_peche.jpg'),(87,'Oualidia','Djellaba d\'été en coton','Habit léger adapté au climat marin et aux journées ensoleillées.','djellaba_coton_ete_oualidia.webp'),(88,'Haut Atlas','Akhnif','Manteau de laine noire avec motif coloré traditionnel.','akhnif_atlas_noir.jpg'),(89,'Haut Atlas','Coiffe de l\'Atlas','Parure féminine ornée de pi├¿ces d\'argent.','coiffe_argent_haut_atlas.webp'),(90,'El Jadida','Kaftan Doukkali','Tenue traditionnelle féminine ornée de broderies spécifiques ├á la région.','kaftan_doukkali_broderie.jpg'),(91,'El Jadida','Habit du Chevalier','Tenue compl├¿te pour la Tbourida (Fantasie) typique de Doukkala.','habit_chevalier_tbourida_doukkala.jfif'),(92,'Ouka├»meden','Djellaba de Laine','Une djellaba tr├¿s épaisse portée par les montagnards locaux pour se protéger du gel.','djellaba_laine_oukaimeden.jpg'),(93,'Ouka├»meden','Accessoires en Laine','Bonnets, gants et chaussettes tricotés ├á la main vendus par les artisans locaux.','accessoires_laine_tricotes.jpg'),(94,'Al Hoceima','Mendil','Tissu rayé rouge et blanc porté par les femmes du Rif.','Mendil_hoceima.png'),(95,'Al Hoceima','Chapeau de paille (Taraza)','Grand chapeau orné de pompons colorés.','Chapeau_paille_hoceima.png'),(96,'Al Hoceima','Jellaba de laine','V├¬tement chaud pour le climat montagnard du Rif.','Jellaba_laine_hoceima.jpg'),(97,'Al Hoceima','Bijoux en argent rifains','Parures traditionnelles avec gravures berb├¿res.','Bijoux_argent_rifains_hoceima.png'),(98,'Imlil','Tacheddirt (Djellaba de montagne)','Laine épaisse pour protéger du froid de l\'Atlas.','Tacheddirt_imlil.png'),(99,'Imlil','Ceinture berb├¿re','Longue ceinture colorée en laine tissée ├á la main.','Ceinture_berb├¿re_imlil.png'),(100,'Imlil','Ch├¿che en laine','Porté par les guides et bergers de haute montagne.','Ch├¿che_laine_imlil.jpg'),(101,'Imlil','Fibules berb├¿res','Broches en argent pour attacher les v├¬tements traditionnels.','Fibules_berb├¿res_imlil.png'),(102,'Ouarzazate','Khandoura de l\'Oasis','V├¬tement léger et coloré adapté ├á la chaleur.','Khandoura_Oasis_ourzazat.png'),(103,'Ouarzazate','Bijoux de l\'Atlas','Colliers d\'ambre et d\'argent massif.','Bijoux_Atlas_Ouarzazate.jpg'),(104,'Ouarzazate','Sarraouel Loubia','Pantalon large traditionnel tr├¿s confortable.','Sarraouel_Loubia_ouarzazate.png'),(105,'Merzouga','Le Ch├¿che Bleu (Tagelmust)','Protection essentielle contre le soleil et le vent du désert.','Ch├¿che_Bleu_merzouga.png'),(106,'Merzouga','Daraa Sahraouia','Grande tunique bleue ample favorisant la circulation de l\'air.','Daraa_Sahraouia.jpg'),(107,'Merzouga','Melhfa','Tissu léger enveloppant le corps des femmes sahraouies.','Melhfa_merzouga.png'),(108,'Merzouga','Sandales en cuir de chameau','Adaptées ├á la marche dans le sable chaud.','Sandales_cuir_chameau_merzouga.png'),(109,'Rabat','Caftan Rbati','Broderie \"Terz Rbati\" connue pour ses motifs floraux fins.','Caftan_Rbati_rabat.jpg'),(110,'Rabat','Djellaba en soie','Portée par les femmes lors des cérémonies.','Djellaba_en_soie_rabat.png'),(111,'Rabat','Babouches brodées','Chaussures artisanales souvent ornées de fil d\'or.','Babouches_brodées_rabat.png'),(112,'Moyen Atlas','Ha├»k Berb├¿re','Habit traditionnel en laine blanche symbolisant la pureté et l\'authenticité.','haik_berbere_laine_atlas.jfif'),(113,'Moyen Atlas','Tachedat','Coiffe traditionnelle ornée d\'argent et de corail, embl├¿me de la femme de l\'Atlas.','tachedat_ambre_argent_atlas.jpg'),(114,'Kelaat M\'Gouna','Djellaba berb├¿re','V├¬tement traditionnel adapté au climat montagnard.','djellaba_berbere.jpg'),(115,'Kelaat M\'Gouna','Ch├óle du Haut Atlas','Tissu chaud porté dans les régions montagneuses.','chale_atlas.jpg'),(116,'Kelaat M\'Gouna','Bijoux berb├¿res','Accessoires artisanaux en argent avec motifs traditionnels.','bijoux_berberes.jpg'),(117,'Kelaat M\'Gouna','Caftan','Tenue traditionnelle portée lors des occasions.','caftan.jpg');
