INSERT INTO `villes` VALUES ('Agadir','La Perle du Sud','Destination balnéaire cél├¿bre pour sa baie et son climat doux.','Villes c├┤ti├¿res',30.427800,-9.598100,'Agadir.png'),('Al Hoceima','La Perle de la Méditerranée','Le Rivage Turquoise, niché au creux des montagnes du Rif. Al Hoceima est une invitation ├á lÔÇÖémerveillement, cél├¿bre pour ses baies sauvages et ses eaux cristallines qui rappellent les plus belles ├«les méditerranéennes.','Villes c├┤ti├¿res',35.251700,-3.937200,'Al_Hoceima.png'),('Asilah','La blanche qui inspire, entre mer et art.','Asilah est une ville c├┤ti├¿re du nord-ouest du Maroc, cél├¿bre pour ses fa├ºades blanches aux volets colorés et ses ruelles pittoresques qui serpentent dans la médina. Reconnue comme une ville de lÔÇÖart, ses murs décorés de fresques et dÔÇÖ┼ôuvres murales refl├¿tent un patrimoine artistique vivant et créatif.\nLÔÇÖambiance paisible, rythmée par le souffle de lÔÇÖocéan Atlantique et les marchés animés, se m├¬le harmonieusement ├á la culture locale. Asilah offre un mélange unique de beauté architecturale, dÔÇÖhéritage culturel et de cadre naturel, o├╣ mer, lumi├¿re et expression artistique créent une atmosph├¿re captivante.','Villes culturelles',35.471500,-6.033600,'Asilah.jpg'),('Azrou','Le C┼ôur de la For├¬t de C├¿dres','Située ├á 1250m d\'altitude, Azrou est une escale incontournable de l\'Atlas, cél├¿bre pour son rocher emblématique et sa nature sauvage.','Villes culturelles',33.433300,-5.216700,'Azrou.png'),('Berkane','La Capitale des Oranges','P├┤le agricole majeur du Maroc Oriental, cél├¿bre pour ses agrumes de qualité mondiale et ses sites préhistoriques uniques.','Villes agricoles',34.920000,-2.320000,'Berkane.jpg'),('Casablanca','La Métropole Blanche','Le battement de c┼ôur moderne du Maroc. Casablanca est une ville de contrastes fascinants, o├╣ les gratte-ciel c├┤toient l\'architecture Art déco. Dominée par la majestueuse mosquée Hassan II, elle incarne l\'énergie, l\'ouverture et l\'élégance contemporaine d\'une cité qui ne dort jamais.','Villes c├┤ti├¿res',33.573100,-7.589800,'Casablanca.webp'),('Chefchaouen','Chefchaouen, la perle bleue du Rif.','Chefchaouen est une ville pittoresque située dans les montagnes du Rif, cél├¿bre pour ses ruelles peintes en bleu, son architecture authentique et son ambiance paisible. La ville offre un mélange unique de culture, dÔÇÖhistoire et de nature, avec des panoramas magnifiques, des marchés artisanaux et une hospitalité chaleureuse qui séduisent tous les visiteurs.','Villes de montagne',35.168800,-5.269000,'Chefchaouen.jpg'),('Dakhla','Entre océan et désert, lÔÇÖaventure au bout du monde.','Dakhla est une ville du sud du Maroc, située sur une presquÔÇÖ├«le entre lÔÇÖocéan Atlantique et le désert du Sahara.\n Elle est réputée pour ses magnifiques plages, ses lagunes, ses dunes et ses paysages désertiques uniques. Destination idéale pour les amateurs de sports nautiques comme le kitesurf et la planche ├á voile, Dakhla offre également un cadre paisible et naturel pour se détendre et profiter du désert.\n Sa combinaison de mer et de désert en fait un lieu exceptionnel pour les aventures en plein air.','Villes c├┤ti├¿res',23.684700,-14.969900,'Dakhla.jpg'),('El Jadida','Mazagan: Cité du Patrimoine','Ancienne cité portugaise classée au patrimoine mondial de l\'UNESCO, cél├¿bre pour ses remparts.','Villes c├┤ti├¿res',33.233300,-8.500000,'El Jadida.jpeg'),('Essaouira','La Cité des Alizés','Essaouira est une escale boh├¿me protégée par ses remparts historiques. Ses ruelles blanches et son port traditionnel créent un tableau d\'une sérénité absolue. CÔÇÖest un havre de paix o├╣ le temps semble sÔÇÖarr├¬ter, bercé par le souffle constant de lÔÇÖAtlantique.','Villes c├┤ti├¿res',31.508500,-9.759500,'Essaouira.jpg'),('F├¿s','L\'├éme Spirituelle du Maroc','Un voyage mystique au c┼ôur du temps. Sa médina, véritable labyrinthe médiéval, est un trésor vivant o├╣ l\'artisanat ancestral et la spiritualité se rencontrent. Entre parfum des épices et splendeur des palais, F├¿s offre une immersion totale dans l\'essence du Maroc authentique.','Villes culturelles',34.033100,-4.999800,'Fes.jpeg'),('Haut Atlas','Le Toit de l\'Afrique','Cha├«ne montagneuse majestueuse abritant les plus hauts sommets du Maroc.','Villes de montagne',31.060000,-7.910000,'Haut_Atlas.jpg'),('Ifrane','La Petite Suisse marocaine','un écrin de pureté au c┼ôur de l\'Atlas. Perchée ├á 1650 m├¿tres d\'altitude, Ifrane est une ville d\'une élégance rare, connue pour son architecture alpine et son calme absolu. Qu\'elle soit drapée de neige ou verdoyante, elle est le sanctuaire idéal pour les amoureux de la nature et du silence.','Villes de montagne',33.527300,-5.106700,'ifrane.jpg'),('Imlil','La Porte des Cimes','Le Sanctuaire du Haut Atlas, blotti au pied du majestueux Toubkal. Imlil est un village berb├¿re dÔÇÖune authenticité rare, o├╣ les maisons en pierre se fondent dans un paysage de vallées verdoyantes.','Villes de montagne',31.135300,-7.923600,'Imlil.png'),('Kelaat M\'Gouna','La Vallée des Roses, entre parfum et tradition.','Kelaat MÔÇÖGouna est une ville située dans la vallée du Dad├¿s, au sud du Maroc, réputée pour ses champs de roses et son cél├¿bre festival des roses.\n Elle offre un paysage unique composé dÔÇÖoasis verdoyantes, de kasbahs traditionnelles et de montagnes arides.\n La ville est un centre important de production dÔÇÖeau de rose et de produits cosmétiques naturels, attirant les visiteurs en qu├¬te dÔÇÖauthenticité, de nature et de culture locale.','Villes agricoles',31.245600,-6.132800,'kelaat_mgouna.jpg'),('Kénitra','La Porte Verte du Gharb','Une ville carrefour entre l\'océan Atlantique, le fleuve Sebou et la for├¬t de la Ma├ómora.','Villes c├┤ti├¿res',34.261000,-6.580200,'kenitra.webp'),('La├óyoune','La Porte du Sahara o├╣ modernité et désert se rencontrent.','La├óyoune est une ville du sud du Maroc, au c┼ôur du Sahara, qui combine modernité et charme désertique.\nElle est entourée de dunes dorées et de paysages arides typiques du désert, offrant un cadre unique pour les amoureux de la nature et des grands espaces.\nElle allie dynamisme urbain et traditions sahariennes, avec des marchés animés, une culture locale riche et un environnement naturel impressionnant qui marque par sa beauté et sa tranquillité.','Villes sahariennes',27.121200,-13.204400,'Laayoune.jpeg'),('Marrakech','Marrakech, la cité rouge au c┼ôur du Maroc.','Marrakech est une ville emblématique du Maroc, connue pour sa médina animée, ses souks colorés, ses palais majestueux et ses jardins luxuriants. Surnommée la \"ville rouge\" ├á cause de ses remparts en pisé, elle allie histoire, culture et modernité. Les visiteurs peuvent découvrir la cél├¿bre place Jemaa el-Fna, des monuments historiques, ainsi quÔÇÖune cuisine riche et variée, tout en profitant de lÔÇÖhospitalité chaleureuse des Marrakchis.','Villes culturelles',31.629500,-7.981100,'Marrakech.jpg'),('Mekn├¿s','Mekn├¿s, la ville impériale au patrimoine vivant.','Mekn├¿s est lÔÇÖune des quatre villes impériales du Maroc, cél├¿bre pour ses remparts majestueux, ses portes historiques et ses monuments datant de lÔÇÖépoque sultanale. La ville allie richesse architecturale, marchés traditionnels et ambiance authentique. Les visiteurs peuvent explorer la médina classée au patrimoine mondial de lÔÇÖUNESCO, découvrir des palais, des jardins et des monuments historiques, tout en profitant de lÔÇÖhospitalité locale.','Villes culturelles',33.895800,-5.547300,'Meknes.jpg'),('Merzouga','Le Royaume des Sables','LÔÇÖInfini Doré, o├╣ les dunes de lÔÇÖErg Chebbi touchent le ciel. Merzouga est une expérience sensorielle unique, un océan de sable aux reflets changeants. Idéal pour la découverte de la magie nomade.','Villes sahariennes',31.080100,-3.983300,'Merzouga.png'),('Moyen Atlas','Le Géant des C├¿dres','C┼ôur battant du Maroc, réputé pour ses for├¬ts de c├¿dres, ses lacs dÔÇÖaltitude et son riche héritage berb├¿re.','Villes de montagne',33.425000,-5.216700,'Moyen Atlas.png'),('Nador','Le Joyau de la Lagune Marchica','Une ville méditerranéenne dynamique située au bord de l\'une des plus belles lagunes du monde, entre mer et montagnes Rifaines.','Villes c├┤ti├¿res',35.166700,-2.933300,'nador.webp'),('Oualidia','La Perle de la Lagune','Station balnéaire paisible cél├¿bre pour sa lagune naturelle, son calme et ses parcs ostréicoles renommés.','Villes c├┤ti├¿res',32.731700,-9.043300,'Oualidia.jpg'),('Ouarzazate','La Porte du Désert','Le Hollywood berb├¿re, o├╣ le sable et le cinéma fa├ºonnent la légende. Ouarzazate est une escale envo├╗tante, cél├¿bre pour ses kasbahs ocre et ses studios mythiques. Un décor cinématographique grandeur nature.','Villes sahariennes',30.933500,-6.937000,'Ouarzazate.webp'),('Oujda','La Cité Millénaire de l\'Orient','Capitale de l\'Oriental, Oujda est une ville d\'histoire et de culture, porte d\'entrée vers le grand Maghreb.','Villes culturelles',34.681400,-1.907800,'oujda.jpg'),('Ouka├»meden','Le Toit de l\'Afrique Blanche','La plus haute station de ski d\'Afrique, située ├á 2 600m d\'altitude, offrant un mélange unique de sport d\'hiver et de culture berb├¿re.','Villes de montagne',31.205200,-7.860100,'Ouka├»meden.jpg'),('Rabat','La Capitale Lumi├¿re','La Cité Impériale entre Histoire et Modernité, o├╣ le Bouregreg embrasse l\'océan. Rabat est une ville d\'une élégance souveraine, m├¬lant jardins verdoyants et monuments majestueux. De la Tour Hassan aux remparts des Oudayas.','Villes c├┤ti├¿res',34.020900,-6.841600,'Rabat.png'),('Safi','Capitale Mondiale de la Céramique','Ville portuaire historique cél├¿bre pour sa poterie artisanale, son patrimoine atlantique et ses falaises majestueuses.','Villes c├┤ti├¿res',32.299400,-9.237200,'SAFI.jpg'),('Sa├»dia','La Perle Bleue o├╣ la mer rencontre la sérénité.','Sa├»dia, est une ville c├┤ti├¿re du nord-est du Maroc, cél├¿bre pour ses longues plages de sable doré et son littoral paisible. La ville allie espaces naturels et vie urbaine, avec des promenades le long de la mer, des quartiers calmes et une ambiance détendue qui refl├¿te la beauté et la sérénité de la c├┤te méditerranéenne.\nSa├»dia est une ville c├┤ti├¿re du nord-est du Maroc, connue pour ses longues plages de sable doré et son littoral paisible. La région se caractérise par un climat doux et ensoleillé, idéal pour profiter de lÔÇÖair marin et des activités liées ├á la mer.\n Sa├»dia combine harmonieusement espaces naturels et vie urbaine, avec des quartiers calmes, des promenades le long du front de mer et une ambiance détendue qui refl├¿te la beauté et la sérénité de la c├┤te méditerranéenne.','Villes c├┤ti├¿res',35.150000,-2.466700,'Saidia.avif'),('Tanger','La ville o├╣ la Méditerranée rencontre lÔÇÖAtlantique.','Tanger est une ville portuaire située au nord du Maroc, ├á lÔÇÖentrée du détroit de Gibraltar. Elle est cél├¿bre pour son mélange unique de cultures, dÔÇÖhistoire et de modernité. Les visiteurs peuvent explorer ses médinas pittoresques, ses plages animées et ses sites historiques, tout en profitant de son ambiance cosmopolite. Tanger offre également une vie culturelle riche avec des musées, des galeries et des festivals qui témoignent de son patrimoine multiculturel.','Villes c├┤ti├¿res',35.759500,-5.834000,'Tanger.png'),('Taourirt','Le Carrefour de l\'Oriental','Ville stratégique reliant l\'Est au reste du Maroc, cél├¿bre pour son patrimoine historique et sa production oléicole.','Villes culturelles',34.407200,-2.897200,'Taourirt.jpg'),('Taroudant','La Petite Marrakech','Une cité médiévale authentique protégée par ses remparts millénaires, au c┼ôur de la vallée du Souss.','Villes culturelles',30.472700,-8.874900,'taroudant.jpg'),('Taza','La Cité des Grottes et des Montagnes','Une ville historique stratégique perchée entre le Rif et l\'Atlas, cél├¿bre pour son patrimoine souterrain unique au monde.','Villes de montagne',34.216700,-4.016700,'Taza.jpg'),('Tétouan','Tétouan, le joyau andalou au c┼ôur du Rif.','Tétouan est une ville située au nord du Maroc, au pied des montagnes du Rif, réputée pour son centre-ville classé au patrimoine mondial de lÔÇÖUNESCO. Elle se distingue par son architecture andalouse, ses ruelles pittoresques et ses marchés traditionnels. Tétouan allie histoire, culture et nature, offrant aux visiteurs des plages magnifiques, des montagnes verdoyantes et une ambiance authentique qui refl├¿te le riche héritage de la région.','Villes culturelles',35.574000,-5.368100,'Tetouan.jpg'),('Zagora','La perle du désert o├╣ lÔÇÖhistoire rencontre les dunes.','Zagora est une perle du désert marocain, nichée au pied des dunes infinies du Sahara. Ses oasis verdoyantes apportent un contraste fascinant avec le sable doré qui sÔÇÖétend ├á perte de vue, tandis que les montagnes lointaines dessinent un horizon majestueux.\n La ville se distingue par son atmosph├¿re paisible et authentique, o├╣ chaque lever et coucher de soleil transforme le paysage en un spectacle unique. Symbole dÔÇÖhistoire et de tradition saharienne, Zagora conserve lÔÇÖempreinte des anciennes routes caravani├¿res, rappelant son r├┤le central dans les échanges ├á travers le désert.','Villes sahariennes',30.326600,-5.837200,'Zagora.jpg');
